<?php

declare(strict_types=1);

namespace Omnitrix\Database\Schema;

use InvalidArgumentException;
use Omnitrix\Core\Database\Query\Expression;

use function array_map;
use function implode;
use function is_bool;
use function is_float;
use function is_int;
use function is_string;
use function str_replace;

/**
 * Compiles {@see Blueprint}s into PostgreSQL DDL. Differences from MySQL:
 *
 * - auto-increment columns are identity columns (`GENERATED BY DEFAULT AS IDENTITY`);
 * - indexes (including unique ones) are separate `CREATE INDEX` statements, so `dropIndex()`
 *   works the same for both; full-text indexes are GIN indexes on `to_tsvector('simple', …)`;
 * - `enum()` is a text column with a CHECK constraint, `json()` is `jsonb`, `binary()` `bytea`;
 * - unsigned, `after()`, the table engine/charset and `useCurrentOnUpdate()` have no PostgreSQL
 *   equivalent and are ignored (models maintain `updated_at` themselves);
 * - comments are `COMMENT ON` statements.
 */
final class PostgresSchemaGrammar implements SchemaGrammarInterface
{
    public function compile(Blueprint $blueprint): array
    {
        return $blueprint->creating ? $this->compileCreate($blueprint) : $this->compileAlter($blueprint);
    }

    /** @return list<string> */
    public function compileCreate(Blueprint $blueprint): array
    {
        $lines = array_map(fn(ColumnDefinition $c): string => $this->column($c), $blueprint->columns());
        foreach ($blueprint->indexes() as $index) {
            if ($index['type'] === 'primary') {
                $lines[] = 'PRIMARY KEY (' . $this->columns($index['columns']) . ')';
            }
        }
        foreach ($blueprint->foreignKeys() as $foreign) {
            $lines[] = $this->foreignClause($blueprint, $foreign);
        }
        $statements = ['CREATE TABLE ' . $this->wrap($blueprint->table) . " (\n    " . implode(",\n    ", $lines) . "\n)"];
        foreach ($blueprint->indexes() as $index) {
            if ($index['type'] !== 'primary') {
                $statements[] = $this->createIndex($blueprint->table, $index);
            }
        }

        return [...$statements, ...$this->comments($blueprint)];
    }

    /** @return list<string> */
    public function compileAlter(Blueprint $blueprint): array
    {
        $table = $this->wrap($blueprint->table);
        $statements = [];
        foreach ($blueprint->droppedForeignKeys() as $name) {
            $statements[] = 'ALTER TABLE ' . $table . ' DROP CONSTRAINT ' . $this->wrap($name);
        }
        foreach ($blueprint->droppedIndexes() as $name) {
            $statements[] = 'DROP INDEX ' . $this->wrap($name);
        }
        foreach ($blueprint->renamedColumns() as $rename) {
            $statements[] = 'ALTER TABLE ' . $table . ' RENAME COLUMN ' . $this->wrap($rename['from']) . ' TO ' . $this->wrap($rename['to']);
        }
        $changes = [];
        foreach ($blueprint->columns() as $column) {
            $changes[] = 'ADD COLUMN ' . $this->column($column);
        }
        foreach ($blueprint->foreignKeys() as $foreign) {
            $changes[] = 'ADD ' . $this->foreignClause($blueprint, $foreign);
        }
        foreach ($blueprint->indexes() as $index) {
            if ($index['type'] === 'primary') {
                $changes[] = 'ADD PRIMARY KEY (' . $this->columns($index['columns']) . ')';
            }
        }
        foreach ($blueprint->droppedColumns() as $column) {
            $changes[] = 'DROP COLUMN ' . $this->wrap($column);
        }
        if ($changes !== []) {
            $statements[] = 'ALTER TABLE ' . $table . ' ' . implode(', ', $changes);
        }
        foreach ($blueprint->indexes() as $index) {
            if ($index['type'] !== 'primary') {
                $statements[] = $this->createIndex($blueprint->table, $index);
            }
        }

        return [...$statements, ...$this->comments($blueprint)];
    }

    public function compileDrop(string $table, bool $ifExists): string
    {
        return 'DROP TABLE ' . ($ifExists ? 'IF EXISTS ' : '') . $this->wrap($table);
    }

    public function compileRename(string $from, string $to): string
    {
        return 'ALTER TABLE ' . $this->wrap($from) . ' RENAME TO ' . $this->wrap($to);
    }

    public function wrap(string $identifier): string
    {
        return '"' . str_replace('"', '""', $identifier) . '"';
    }

    public function currentSchema(): string
    {
        return 'current_schema()';
    }

    public function compileDropAll(array $tables): array
    {
        return $tables === [] ? [] : ['DROP TABLE IF EXISTS ' . implode(', ', array_map($this->wrap(...), $tables)) . ' CASCADE'];
    }

    public function column(ColumnDefinition $column): string
    {
        $sql = $this->wrap($column->name) . ' ' . $this->type($column);
        if ($column->collation !== null) {
            $sql .= ' COLLATE ' . $this->wrap($column->collation);
        }
        if ($column->autoIncrement) {
            $sql .= ' GENERATED BY DEFAULT AS IDENTITY';
        } elseif ($column->useCurrent) {
            $sql .= ' DEFAULT CURRENT_TIMESTAMP';
        } elseif ($column->hasDefault) {
            $sql .= ' DEFAULT ' . $this->defaultValue($column->default);
        }
        $sql .= $column->nullable && !$column->autoIncrement ? ' NULL' : ' NOT NULL';
        if ($column->type === 'enum') {
            $sql .= ' CHECK (' . $this->wrap($column->name) . ' IN (' . implode(', ', array_map($this->quote(...), $this->values($column->parameters['values'] ?? []))) . '))';
        }
        if ($column->primary) {
            $sql .= ' PRIMARY KEY';
        }

        return $sql;
    }

    private function type(ColumnDefinition $column): string
    {
        $p = $column->parameters;
        $int = static fn(string $key, int $default): int => is_int($p[$key] ?? null) ? $p[$key] : $default;

        return match ($column->type) {
            'varchar' => 'VARCHAR(' . $int('length', 255) . ')',
            'char' => 'CHAR(' . $int('length', 255) . ')',
            'text', 'mediumtext', 'longtext' => 'TEXT',
            'enum' => 'VARCHAR(255)',
            'json' => 'JSONB',
            'blob' => 'BYTEA',
            'tinyint', 'smallint' => 'SMALLINT',
            'int' => 'INTEGER',
            'bigint' => 'BIGINT',
            'float' => 'REAL',
            'double' => 'DOUBLE PRECISION',
            'decimal' => 'DECIMAL(' . $int('precision', 8) . ', ' . $int('scale', 2) . ')',
            'boolean' => 'BOOLEAN',
            'date' => 'DATE',
            'time' => 'TIME',
            'datetime', 'timestamp' => 'TIMESTAMP(' . $int('precision', 0) . ')',
            default => throw new InvalidArgumentException("Unsupported column type '{$column->type}'"),
        };
    }

    /** @param array{type: string, columns: list<string>, name: string} $index */
    private function createIndex(string $table, array $index): string
    {
        $target = $this->wrap($table);
        if ($index['type'] === 'fulltext') {
            $document = implode(" || ' ' || ", array_map(fn(string $c): string => "coalesce({$this->wrap($c)}::text, '')", $index['columns']));

            return 'CREATE INDEX ' . $this->wrap($index['name']) . ' ON ' . $target . " USING gin (to_tsvector('simple', {$document}))";
        }

        return 'CREATE ' . ($index['type'] === 'unique' ? 'UNIQUE ' : '') . 'INDEX ' . $this->wrap($index['name']) . ' ON ' . $target . ' (' . $this->columns($index['columns']) . ')';
    }

    private function foreignClause(Blueprint $blueprint, ForeignKeyDefinition $foreign): string
    {
        if ($foreign->on === null) {
            throw new InvalidArgumentException('Foreign key on ' . implode(', ', $foreign->columns) . " of '{$blueprint->table}' needs a referenced table (->on())");
        }
        $name = $foreign->name ?? $blueprint->indexName('foreign', $foreign->columns);

        return 'CONSTRAINT ' . $this->wrap($name) . ' FOREIGN KEY (' . $this->columns($foreign->columns) . ')'
            . ' REFERENCES ' . $this->wrap($foreign->on) . ' (' . $this->columns($foreign->references) . ')'
            . ' ON DELETE ' . $foreign->onDelete . ' ON UPDATE ' . $foreign->onUpdate;
    }

    /** @return list<string> */
    private function comments(Blueprint $blueprint): array
    {
        $statements = [];
        if ($blueprint->comment !== null) {
            $statements[] = 'COMMENT ON TABLE ' . $this->wrap($blueprint->table) . ' IS ' . $this->quote($blueprint->comment);
        }
        foreach ($blueprint->columns() as $column) {
            if ($column->comment !== null) {
                $statements[] = 'COMMENT ON COLUMN ' . $this->wrap($blueprint->table) . '.' . $this->wrap($column->name) . ' IS ' . $this->quote($column->comment);
            }
        }

        return $statements;
    }

    /** @param list<string> $columns */
    private function columns(array $columns): string
    {
        return implode(', ', array_map($this->wrap(...), $columns));
    }

    /**
     * @param int|list<string> $values
     *
     * @return list<string>
     */
    private function values(int|array $values): array
    {
        return is_int($values) ? [] : $values;
    }

    private function defaultValue(string|int|float|bool|Expression|null $value): string
    {
        return match (true) {
            $value === null => 'NULL',
            is_bool($value) => $value ? 'TRUE' : 'FALSE',
            is_int($value), is_float($value) => (string) $value,
            is_string($value) => $this->quote($value),
            default => $value->sql,
        };
    }

    private function quote(string $value): string
    {
        // standard_conforming_strings is on by default: only the quote is escaped.
        return "'" . str_replace("'", "''", $value) . "'";
    }
}
